mapper.update:
update cs_retain_details set
  branch_key = #{dto.branchKey, jdbcType=VARCHAR},
  target_branch_key = #{dto.targetBranchKey, jdbcType=VARCHAR}
where branch_uuid = #{dto.branchUuid, jdbcType=VARCHAR}

mapper.sql:
insert into cs_issue_track_for_retain ( branch_uuid, issue_kee, retained_status, rule_uuid, component_key, message, severity, issue_type, tags, assignee_uuid, status_marked_by_uuid, issue_creation_date, status_changed_at ) select i.project_uuid, i.kee, #{retainedStatus, jdbcType=VARCHAR}, i.rule_uuid, c.kee, i.message, i.severity, i.issue_type, i.tags, i.assignee, #{statusMarkedByUuid, jdbcType=VARCHAR}, i.issue_creation_date,
coalesce(i.issue_close_date, #{now, jdbcType=BIGINT}) from issues i left join components c on c.uuid = i.component_uuid where i.kee in
#{issueKey, jdbcType=VARCHAR}
and i.project_uuid = #{branchUuid, jdbcType=VARCHAR} and i.issue_type <> #{excludedIssueType, jdbcType=INTEGER}
and (i.status = 'CLOSED' or (i.status = 'RESOLVED' and i.resolution = 'FIXED'))
and i.rule_uuid is not null

mapper.delete:
delete from cs_issue_track_for_retain
where
  retained_status = #{retainedStatus, jdbcType=VARCHAR}
  and issue_kee in

    #{issueKey, jdbcType=VARCHAR}



  and not exists (
    select 1 from issues i
    where i.kee = cs_issue_track_for_retain.issue_kee
      and (i.status = 'CLOSED' or (i.status = 'RESOLVED' and i.resolution = 'FIXED'))
  )

delete from cs_issue_track_for_retain
where branch_uuid in (
  select d.branch_uuid
  from cs_retain_details d
  where d.project_uuid = #{projectUuid, jdbcType=VARCHAR}
)
